<?php $editing=isset($p); ?><form class="form" method="post" enctype="multipart/form-data"><?=csrf_field()?><label>Title</label><input name="title" value="<?=e($p['title']??'')?>" required><label>Slug</label><input name="slug" value="<?=e($p['slug']??'')?>" placeholder="auto-generated"><label>Excerpt</label><textarea name="excerpt"><?=e($p['excerpt']??'')?></textarea><label>Content (HTML is stored as provided; only trusted editors should publish HTML)</label><textarea name="content" rows="18" required><?=e($p['content']??'')?></textarea><label>Category</label><select name="category_id"><option value="">None</option><?php foreach(db()->query("SELECT id,name FROM categories ORDER BY name") as $c):?><option value="<?=$c['id']?>" <?=((int)($p['category_id']??0)==$c['id'])?'selected':''?>><?=e($c['name'])?></option><?php endforeach;?></select><label>Status</label><select name="status"><?php foreach(['draft','published','scheduled'] as $s):?><option <?=((($p['status']??'draft')===$s)?'selected':'')?>><?=$s?></option><?php endforeach;?></select><label>Publish date</label><input type="datetime-local" name="published_at" value="<?=isset($p['published_at'])?date('Y-m-d\TH:i',strtotime($p['published_at'])):date('Y-m-d\TH:i')?>"><label>SEO title</label><input name="seo_title" value="<?=e($p['seo_title']??'')?>"><label>SEO description</label><textarea name="seo_description"><?=e($p['seo_description']??'')?></textarea><button>Save</button></form>